            if (IsActiveThreadTerminating()) return _Fail_Val.Return();
            if (followers[i].MsgGetThingsKilled(KilledCreatures)) {
                if (IsActiveThreadTerminating()) return _Fail_Val.Return();
                Killed += KilledCreatures.size();
                KilledCreatures.clear();
            }
