    bool Loaded() const { return Frame >= LoadedAt; }
    void Run()
    {
        long killed = 0;
        for (; !false; NSF()) {
            if (T()) return;
            if (!Loaded()) {
                if (T()) return;
                while (!Loaded()) {
                    NSF();
                    if (T()) return;
                }
                if (T()) return;
