            }
            for (int i = 0; i < Followers; i++) {
                if (T()) return;
                if (FollowerKills[Frame & 7]) {
                    if (T()) return;
                    killed += FollowerKills[Frame & 7];
                }
            }
            if (T()) return;
            for (int i = 0; i < Summons; i++) {
                if (T()) return;
                if (SummonKills[Frame & 7]) {
                    if (T()) return;
                    killed += SummonKills[Frame & 7];
                }
